const docWindow=root=>root.ownerDocument.defaultView||window;
import{escapeStaff as esc,staffIcon as icon,roleLabel}from './staff-markup.js';
const initials=name=>[...String(name||'С').trim()].slice(0,2).join('').toUpperCase();
export function staffMessengerMarkup(){return '<div class="staff-chat staff-messenger" data-messenger-view="list"><aside class="staff-chat-side"><header class="staff-inbox-heading"><h2>Переписки</h2><span class="staff-inbox-count" data-inbox-count></span><button type="button" class="staff-icon-button" data-new-message aria-label="Новое сообщение" aria-pressed="false">'+icon('plus')+'</button></header><label class="staff-chat-search">'+icon('messages')+'<input type="search" maxlength="80" aria-label="Найти переписку" placeholder="Найти переписку"></label><nav class="staff-inbox-filters" aria-label="Переписки"><button type="button" data-inbox-filter="all" aria-pressed="true">Все</button><button type="button" data-inbox-filter="direct" aria-pressed="false">Личные</button><button type="button" data-inbox-filter="team" aria-pressed="false">Общий чат</button></nav><h3 class="staff-inbox-label">Переписки</h3><div data-rooms></div><h3 class="staff-inbox-label">Написать сотруднику</h3><div data-contacts></div></aside><dialog class="staff-conversation-window" aria-label="Переписка"><section class="staff-conversation"><header class="staff-chat-heading"><button type="button" class="staff-icon-button" data-messenger-back aria-label="К перепискам">'+icon('back')+'</button><span class="staff-conversation-avatar" aria-hidden="true" data-conversation-avatar>С</span><div><strong data-chat-title>Команда SALAH</strong><small data-chat-subtitle>Общий чат команды</small></div></header><div data-staff-push-control></div><p class="staff-conversation-status" role="status" hidden></p><div class="staff-chat-messages" role="log" aria-label="Переписка" aria-live="polite" aria-relevant="additions text"></div><form class="staff-composer"><div class="staff-pending-files"></div><div class="staff-emoji" hidden>'+['🙂','😊','🤍','👍','🤲','🙏','✨','🌙','✅','👏','💬','📌'].map(x=>'<button type="button" data-emoji="'+x+'" aria-label="'+x+'">'+x+'</button>').join('')+'</div><div class="staff-composer-row"><button class="staff-icon-button" type="button" data-smile aria-label="Смайлики" aria-expanded="false">'+icon('smile')+'</button><button class="staff-icon-button" type="button" data-attach aria-label="Прикрепить файл">'+icon('file')+'</button><textarea maxlength="5000" aria-label="Сообщение" placeholder="Напишите сообщение…"></textarea><button class="staff-icon-button staff-send" type="submit" aria-label="Отправить">'+icon('send')+'</button><input type="file" hidden multiple data-chat-file accept=".pdf,.txt,.jpg,.jpeg,.png,.zip,.docx,.xlsx,.pptx"></div></form></section></dialog></div>';}
export function mountStaffMessenger(root,{rooms=[],contacts=[],onRoom,onContact,onRendered=()=>{},initialRoom=null}={}){
 const win=docWindow(root),doc=root.ownerDocument,dialog=root.querySelector('dialog'),input=root.querySelector('textarea'),list=root.querySelector('[data-rooms]'),people=root.querySelector('[data-contacts]'),search=root.querySelector('input[type=search]'),newButton=root.querySelector('[data-new-message]');
 const history=win.history,historyKey='salahStaffChat',token=String(Date.now())+'-'+Math.random().toString(36).slice(2);let selected=null,filter='all',query='',newMessage=false,disposed=false,previousState=null,narrow=true,wasModal=false,backPending=false;
 const ownsEntry=()=>history?.state?.[historyKey]===token;
 const stripMarker=()=>{if(history?.state?.[historyKey]){const state={...history.state};delete state[historyKey];history.replaceState(state,'',win.location.href);}};
 stripMarker();
 function viewport(){if(disposed)return;const box=root.getBoundingClientRect();narrow=(win.innerWidth||0)<720||box.width<600;const height=win.visualViewport?.height||win.innerHeight||800,top=win.visualViewport?.offsetTop||0;root.style.setProperty('--staff-conversation-height',Math.round(Math.min(740,height-100))+'px');dialog.style.setProperty('--staff-chat-viewport-height',Math.round(height)+'px');dialog.style.setProperty('--staff-chat-viewport-top',Math.round(top)+'px');const modal=narrow&&root.dataset.messengerView==='chat';doc.body.classList.toggle('staff-messenger-open',modal);dialog.classList.toggle('is-mobile',narrow);
  if(modal){if(dialog.open&&!wasModal)dialog.close();if(!dialog.open){dialog.showModal();root.querySelector('[data-messenger-back]').focus({preventScroll:true});}wasModal=true;}
  else{if(dialog.open&&wasModal)dialog.close();wasModal=false;if(!narrow&&!dialog.open)dialog.show();if(narrow&&dialog.open)dialog.close();}
 }
 const typing=()=>{if(disposed)return;doc.body.classList.toggle('staff-messenger-typing',narrow&&doc.activeElement===input);viewport();};
 const onBlur=()=>queueMicrotask(typing);input.addEventListener('focus',typing);input.addEventListener('blur',onBlur);
 const resizeInput=()=>{input.style.height='auto';input.style.height=Math.max(46,Math.min(124,input.scrollHeight||46))+'px';};input.addEventListener('input',resizeInput);
 const roomTitle=room=>room.title||'Переписка';
 function renderRooms(rows=rooms,current=selected){if(disposed)return;rooms=rows;selected=current;const count=rooms.reduce((sum,r)=>sum+(Number.isSafeInteger(r.unread)&&r.unread>0?r.unread:0),0);root.querySelector('[data-inbox-count]').textContent=count?(count>99?'99+':String(count)):'';
  const visible=rooms.filter(r=>(filter==='all'||(filter==='team')===(r.kind==='team'))&&roomTitle(r).toLowerCase().includes(query));
  list.hidden=newMessage;list.previousElementSibling.hidden=true;
  list.innerHTML=visible.length?visible.map(r=>'<button type="button" class="staff-chat-room" data-room="'+esc(r.id)+'" aria-current="'+(r.id===selected?.id)+'"><span class="staff-room-avatar'+(r.peerId?' staff-avatar':'')+'"'+(r.peerId?' data-member-avatar="'+esc(r.peerId)+'"':'')+' aria-hidden="true">'+(r.kind==='team'?icon('team'):esc(initials(roomTitle(r))))+'</span><span class="staff-room-copy"><strong>'+esc(roomTitle(r))+'</strong><small>'+esc(r.last_message||'Начните разговор')+'</small></span>'+(r.unread?'<span class="staff-room-unread" aria-label="Непрочитанных: '+esc(r.unread)+'">'+esc(r.unread>99?'99+':r.unread)+'</span>':'')+'</button>').join(''):'<p class="staff-empty">'+(query?'Переписки не найдены.':'Здесь пока нет переписок.')+'</p>';
  const showPeople=filter!=='team'&&(newMessage||!!query);people.hidden=!showPeople;people.previousElementSibling.hidden=!showPeople;people.innerHTML=showPeople?contacts.filter(p=>String(p.nickname||'').toLowerCase().includes(query)).map(p=>'<button type="button" class="staff-chat-room staff-chat-contact" data-contact="'+esc(p.id)+'"><span class="staff-avatar staff-room-avatar" data-member-avatar="'+esc(p.id)+'" aria-hidden="true">'+esc(initials(p.nickname))+'</span><span class="staff-room-copy"><strong>'+esc(p.nickname)+'</strong><small>'+esc(roleLabel(p.role))+'</small></span></button>').join(''):'';
  if(showPeople&&!people.childElementCount)people.innerHTML='<p class="staff-empty">Сотрудники не найдены.</p>';newButton.setAttribute('aria-pressed',String(newMessage));newButton.setAttribute('aria-label',newMessage?'К перепискам':'Новое сообщение');onRendered();
 }
 function showConversation(room){if(disposed||!room||backPending)return;selected=room;const opening=root.dataset.messengerView!=='chat';root.dataset.messengerView='chat';root.querySelector('[data-chat-title]').textContent=roomTitle(room);root.querySelector('[data-chat-subtitle]').textContent=room.kind==='team'?'Общий чат команды':'Личная переписка';const avatar=root.querySelector('[data-conversation-avatar]');if(room.peerId){avatar.dataset.memberAvatar=room.peerId;avatar.classList.add('staff-avatar');}else{delete avatar.dataset.memberAvatar;avatar.classList.remove('staff-avatar');}avatar.innerHTML=room.kind==='team'?icon('team'):esc(initials(roomTitle(room)));renderRooms(rooms,selected);viewport();if(opening&&narrow&&history&&!ownsEntry()){previousState=history.state;try{history.pushState({...previousState,[historyKey]:token},'',win.location.href);}catch{}}
 }
 function showList({back=false}={}){if(disposed)return;root.dataset.messengerView='list';input.blur();doc.body.classList.remove('staff-messenger-typing');viewport();const heading=root.querySelector('.staff-inbox-heading h2');heading.tabIndex=-1;heading.focus({preventScroll:true});if(back&&!backPending&&ownsEntry()){backPending=true;history.back();}}
 const pop=()=>{if(disposed)return;backPending=false;if(root.dataset.messengerView==='chat'&&!ownsEntry())showList();else if(ownsEntry()&&root.dataset.messengerView!=='chat')stripMarker();};win.addEventListener('popstate',pop);
 const cancel=e=>{e.preventDefault();showList({back:true});};dialog.addEventListener('cancel',cancel);root.querySelector('[data-messenger-back]').onclick=()=>showList({back:true});
 list.onclick=e=>{const b=e.target.closest('[data-room]');if(b)onRoom(rooms.find(r=>r.id===b.dataset.room));};people.onclick=e=>{const b=e.target.closest('[data-contact]');if(b)onContact(b.dataset.contact);};
 search.oninput=()=>{query=search.value.trim().toLowerCase();renderRooms();};newButton.onclick=()=>{newMessage=!newMessage;filter='all';for(const b of root.querySelectorAll('[data-inbox-filter]'))b.setAttribute('aria-pressed',String(b.dataset.inboxFilter===filter));renderRooms();};for(const button of root.querySelectorAll('[data-inbox-filter]'))button.onclick=()=>{filter=button.dataset.inboxFilter;newMessage=false;for(const b of root.querySelectorAll('[data-inbox-filter]'))b.setAttribute('aria-pressed',String(b===button));renderRooms();};
 win.addEventListener('resize',viewport);win.visualViewport?.addEventListener('resize',viewport);win.visualViewport?.addEventListener('scroll',viewport);renderRooms();viewport();if(initialRoom){const row=rooms.find(r=>r.id===initialRoom);if(row)showConversation(row);}
 return{renderRooms,showConversation,isConversationVisible:()=>root.dataset.messengerView==='chat'||!narrow,dispose(){if(disposed)return;disposed=true;if(ownsEntry())history.replaceState(previousState,'',win.location.href);if(dialog.open)dialog.close();doc.body.classList.remove('staff-messenger-typing','staff-messenger-open');input.removeEventListener('focus',typing);input.removeEventListener('blur',onBlur);input.removeEventListener('input',resizeInput);win.removeEventListener('resize',viewport);win.removeEventListener('popstate',pop);win.visualViewport?.removeEventListener('resize',viewport);win.visualViewport?.removeEventListener('scroll',viewport);dialog.removeEventListener('cancel',cancel);}};
}
